-- level:2.2
INSERT INTO content_text (doc_id, revision, text, updated_at, updated_by) VALUES ('level:2.2', 1, '{"location":"Hàng Rào Ngoài","briefing":"[NHẬT KÝ CẢM BIẾN – HÀNG RÀO NGOÀI]\nMột drone bay dọc hàng rào theo chu kỳ. Mỗi lượt bay qua, nó đo khoảng cách tới Kai rồi so với tầm quét của nó.\nKai cần một lệnh cho mỗi lượt: đi hoặc nấp. Mặc định là đi.\nLệnh chỉ đổi thành nấp khi drone đang ở trong tầm quét, tức là khi khoảng cách không vượt quá tầm quét. Mỗi drone có một tầm quét riêng.","task_steps":["Bấm CHẠY một lần và đọc dòng Python báo lỗi. Dòng nằm ngay dưới `if` phải lùi vào thì mới thuộc về `if` đó.","Biến `lenh` giữ lệnh của Kai. Nó có một giá trị mặc định và chỉ đổi khi drone ở trong tầm quét. Luật đầy đủ nằm ở ô Mục tiêu.","Sau mỗi lượt chạy, xem dòng nào bị làm mờ trong editor: đó là dòng không chạy ở tình huống đang hiện. Xét kỹ tình huống drone đứng đúng mép tầm quét.","Hoàn thành khi mục tiêu chuyển thành xanh ở cả ba tình huống. Dùng không quá 3 câu lệnh và qua được lượt OMNI đổi tầm quét thì được thêm sao."],"objectives":[{"var":"lenh","label":"Lệnh của Kai: `NAP` khi khoảng cách không vượt quá tầm quét, còn lại `DI`"}],"hints":["Python báo lỗi ở dòng 8. Một dòng nằm dưới `if` phải lùi vào 4 dấu cách thì mới thuộc khối của `if` đó. Sửa xong, đọc điều kiện ở dòng 7 thành lời: nó đang hỏi drone ở trong tầm quét hay ở ngoài tầm quét?","Gán lệnh mặc định trước. Sau đó kiểm điều kiện, và trong khối của nó gán lệnh còn lại. Thứ tự hai lệnh gán quyết định kết quả.\nSau mỗi lượt, xem dòng nào bị làm mờ trong editor: dòng mờ là dòng không chạy ở tình huống đó. Xét riêng tình huống drone đứng đúng mép tầm quét, như ở bài trước.\nlệnh = đi\nnếu drone ở trong tầm quét (kể cả đứng đúng mép):\n    lệnh = nấp","Mảnh tài liệu Python còn đọc được:\nif dieu_kien:\n    lenh_1\n    lenh_2\nDòng `if` kết thúc bằng dấu `:`. Khối là các dòng lùi vào 4 dấu cách ngay bên dưới. Khối chỉ chạy khi điều kiện là `True`.\nve = \"THUONG\"\nif tuoi >= 60:\n    ve = \"MIEN PHI\"\nGán giá trị mặc định trước `if`, rồi gán đè trong khối.\nThân `if` không lùi vào → IndentationError: expected an indented block after ''if'' statement on line …"],"reactions":{"entry":"Hàng Rào Ngoài. Lần này luật là của Kai, không phải của OMNI. Chạy một lần… rồi đọc xem Python nói gì.","wrong_branch":"Mã đã đi một đường có thật… nhưng là đường dành cho một tình huống khác. Xem drone bắt được Kai ở tình huống nào. Dòng bị làm mờ trong editor là dòng đã không chạy.","type_mismatch":"Ở tình huống {round}, {vars} đang giữ một giá trị đúng hoặc sai, không phải một lệnh. Chip của Kai chỉ nhận lệnh bằng chữ.","type_mismatch_value_match":"{vars} có đúng chữ cần có, nhưng sai kiểu. Chip của Kai vẫn từ chối.","wrong_value":"Ở tình huống {round}, chip của Kai nhận một lệnh mà drone không hiểu. Lệnh phải đúng từng ký tự như ở ô Mục tiêu, kể cả chữ hoa.","missing_var":"Ở tình huống {round}, Kai không nhận được lệnh nào. Có một đường chạy qua mã mà {vars} chưa từng được gán.","SyntaxError":"Dòng {line}. Python không đọc được dòng này, nên chưa câu lệnh nào chạy. Đọc dòng Python báo trong terminal.","IndentationError":"Dòng {line}. Python không biết dòng này có thuộc về điều kiện phía trên hay không. Một khối lệnh phải nhìn ra được là khối.","TypeError":"Dòng {line}. TypeError. Phép tính vừa nhận một giá trị sai kiểu. Cảm biến không đọc được.","ValueError":"Dòng {line}. ValueError. Giá trị này không dùng được cho phép tính đó.","NameError":"Dòng {line}. NameError. Dòng này gọi một cái tên chưa từng có. Soát từng ký tự… nhất là tên các số đo của cảm biến.","ZeroDivisionError":"Dòng {line}. Chia cho không. Python dừng chương trình ngay tại đó.","AttributeError":"Dòng {line}. AttributeError. Dữ liệu này không mang thứ bạn đang gọi.","runtime_error":"Dòng {line}. {error_type}. Chương trình dừng giữa chừng. Đọc dòng truy vết.","timeout":"Mã chạy quá lâu. Tôi cắt kết nối… trước khi drone lần ra dấu.","resource_limit":"Bộ nhớ quá tải. Tôi cắt tiến trình… để laptop còn sống.","blocked_import":"Mô-đun đó bị phong tỏa. Ở đây, ta chỉ có những gì đang cầm trong tay.","input_unsupported":"Không có ai ở đầu kia để trả lời. Số đo đã nằm sẵn trên cảm biến.","system_exit":"Chương trình tự dừng giữa chừng. Kai không nhận được lệnh nào.","alert_exceeded":"Lệnh đúng. Nhưng {count} câu lệnh… mỗi lệnh là một lần drone có thể nghe thấy. Viết gọn hơn.","counter_ValueError":"OMNI đổi drone. Dòng {line} lỗi: ValueError. Số đo mới mang giá trị bạn chưa lường tới.","counter_error":"OMNI đổi drone. Dòng {line}: {error_type}. Mã không chạy được với số đo mới.","counter_type_mismatch":"Drone mới đi qua mã của bạn… và {vars} ra sai kiểu. Chip của Kai không đọc được.","wrong_value_counter":"OMNI đổi drone, mà lệnh của Kai không đổi theo. Chip nhận một lệnh không có trong luật.","counter_timeout":"OMNI đổi drone. Mã của bạn treo với số đo mới… Tôi cắt kết nối. Lối qua chỉ mở một nửa.","two_stars":"Lối qua mở một nửa. Kai qua mà không để lại dấu vết.","three_stars":"Drone đổi, luật của Kai vẫn đúng. Lối qua mở hẳn.","repeated_fail":"Cùng một lỗi, lần thứ {count}. Nhật ký gợi ý vẫn ở đây. Tôi chỉ hỏi được… không trả lời thay.","engine_error":"Lõi Python không phản hồi. Đang khởi động lại…","generic":"Có gì đó không khớp. Đọc lại cảm biến và chip lệnh của Kai."},"reaction_variants":{"wrong_branch":"Vẫn nhầm đường. Lần này nhìn kỹ tình huống drone đứng sát mép tầm quét… ở đó Kai đang trong tầm hay ngoài tầm?","IndentationError":"Vẫn dòng {line}. Python nhìn lề trái để biết dòng nào thuộc khối nào.","missing_var":"Lại không có lệnh ở tình huống {round}. Khi khối không chạy, {vars} lấy giá trị từ đâu?"},"counter_attack_banner":"CẢNH BÁO: OMNI ĐÃ ĐỔI DRONE, TẦM QUÉT ĐÃ KHÁC","outro":"Drone bay qua đầu Kai mà không quay đèn. Trong bộ nhớ đệm của một trụ rào còn một tệp cũ, không thuộc dữ liệu tuần tra:","lore_fragment":"KTS-01: Tôi đặt tên cho mảnh này là Quyết định. Không có nó, công tắc biết cách tắt OMNI… nhưng không biết khi nào thì được tắt. Một công tắc như thế còn nguy hiểm hơn không có gì.","component":"Lệnh nấp","outro_beats":[{"kind":"card","text":"TÍN HIỆU · 0xA7\n\"Bạn đi chậm quá. Lịch của tôi nhanh hơn bạn nhiều.\""},{"kind":"echo","text":"Phía trước là Bãi Container. Đèn pha ở đó quét qua lại cả hai phía… không có chỗ nào đứng yên được lâu."},{"kind":"kai","text":"Tôi đi tiếp. Theo luật của tôi."}],"knowledge_summary":{"title":"Câu lệnh `if` và khối lệnh","sections":[{"heading":"Điều kiện đúng thì khối chạy","body":"`if điều_kiện:` kiểm một điều kiện. Dòng `if` kết thúc bằng dấu `:`. Các dòng lùi vào 4 dấu cách ngay bên dưới là khối lệnh của nó. Điều kiện là `True` thì khối chạy. Dòng không lùi vào nằm ngoài khối."},{"heading":"Điều kiện sai thì khối bị bỏ qua","body":"Điều kiện là `False` thì Python bỏ qua cả khối và đi tiếp xuống dòng sau khối. Ở ví dụ này, `Sot` không được in ra."},{"heading":"Khối có thể nhiều dòng","body":"Mọi dòng lùi vào cùng một mức ngay dưới `if` đều thuộc khối. Chúng cùng chạy, hoặc cùng bị bỏ qua. Khối kết thúc ở dòng đầu tiên không lùi vào nữa."},{"heading":"Giá trị mặc định rồi gán đè","body":"Gán cho biến một giá trị mặc định trước `if`. Trong khối, gán đè giá trị khác khi điều kiện đúng. Điều kiện sai thì biến giữ giá trị mặc định. Thứ tự hai lệnh gán quyết định kết quả: lệnh gán chạy sau cùng sẽ thắng."},{"heading":"Điều kiện là một phép so sánh","body":"Điều kiện thường là một trong sáu phép so sánh của bài trước: `==`, `!=`, `<`, `<=`, `>`, `>=`. Cẩn thận ở điểm bằng nhau: với `tuoi = 18`, `tuoi >= 18` là `True` nhưng `tuoi > 18` là `False`."}],"mistakes":[{"code":"x = 7\nif x > 5:\nprint(\"Lon\")","explain":"Dòng `print` không lùi vào, nên Python không thấy khối nào sau `if`. Lùi dòng đó vào 4 dấu cách."},{"code":"x = 7\nif x > 5\n    print(\"Lon\")","explain":"Dòng `if` thiếu dấu `:` ở cuối."},{"code":"x = 7\nif x = 5:\n    print(\"Nam\")","explain":"`=` là phép gán, không dùng được trong điều kiện. Muốn so sánh bằng nhau thì viết `==`."},{"code":"diem = 4\nif diem >= 5:\n    kq = \"DAT\"\nprint(kq)","explain":"Điều kiện sai nên khối không chạy, và `kq` chưa từng được gán. Gán giá trị mặc định cho `kq` trước `if`."},{"code":"diem = 7\nif diem >= 5:\n    kq = \"DAT\"\nkq = \"TRUOT\"\nprint(kq)","explain":"Lệnh gán mặc định nằm sau khối, nên nó luôn chạy sau cùng và ghi đè kết quả của khối. Đặt nó lên trước `if`."}],"next":"Khi chỉ có hai ngả, phần \"còn lại\" của một điều kiện có từ khóa riêng: `else`. Màn sau dùng nó."}}', '2026-10-29T19:59:39.804Z', 'migration') ON CONFLICT(doc_id) DO NOTHING;
INSERT INTO content_text_history (doc_id, revision, text, saved_at, saved_by) SELECT doc_id, revision, text, updated_at, updated_by FROM content_text WHERE doc_id = 'level:2.2' AND revision = 1 AND updated_by = 'migration' ON CONFLICT(doc_id, revision) DO NOTHING;
